function stripHtml(html = '') {
  return String(html)
    .replace(/<[^>]*>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const inputItems = $input.all();
const allJobs = [];

for (const item of inputItems) {

  const data = item.json;

  if (Array.isArray(data)) {

    for (const job of data) {

      if (!job.position) continue;

      allJobs.push({
        title: job.position || '',
        company: job.company || '',
        location: job.location || 'Remote',
        url: (job.url || '').split('?')[0].trim(),
        apply_url: job.apply_url || '',
        description: stripHtml(job.description || ''),
        tags: Array.isArray(job.tags)
          ? job.tags.join(', ')
          : '',
        salary:
          job.salary_min && job.salary_max
            ? `${job.salary_min} - ${job.salary_max}`
            : '',
        source: 'RemoteOK',
        posted_at: job.date || job.iso_date || null
      });

    }

  }

  if (data.jobs) {

    for (const job of data.jobs) {

      allJobs.push({
        title: job.title || '',
        company: job.company_name || '',
        location: job.candidate_required_location || 'Remote',
        url: (job.url || '').split('?')[0].trim(),
        apply_url: job.url || '',
        description: stripHtml(job.description || ''),
        tags: Array.isArray(job.tags)
          ? job.tags.join(', ')
          : '',
        salary: job.salary || '',
        source: 'Remotive',
        posted_at: job.publication_date || null
      });

    }

  }

  if (data.title && data.link) {

    allJobs.push({
      title: data.title || '',
      company: '',
      location: 'Remote',
      url: (data.link || '').split('?')[0].trim(),
      apply_url: data.link || '',
      description: stripHtml(data.contentSnippet || data.content || ''),
      tags: '',
      salary: '',
      source: 'RSS',
      posted_at: data.isoDate || data.pubDate || null
    });

  }

  if (data.results) {

    for (const job of data.results) {

      allJobs.push({
        title: job.title || '',
        company: job.company?.display_name || '',
        location: job.location?.display_name || 'Remote',
        url: (job.redirect_url || '').split('?')[0].trim(),
        apply_url: job.redirect_url || '',
        description: stripHtml(job.description || ''),
        tags: job.category?.label || '',
        salary:
          job.salary_min && job.salary_max
            ? `${job.salary_min} - ${job.salary_max}`
            : '',
        source: 'Adzuna',
        posted_at: job.created || null
      });

    }

  }

}

const allowed = [
  'react',
  'next.js',
  'nextjs',
  'mern',
  'node',
  'node.js',
  'nestjs',
  'react native',
  'typescript',
  'javascript',
  'fullstack',
  'frontend',
  'backend',
  'software engineer',
  'software developer',
  'web developer',
  'ai engineer',
  'automation',
  'openai',
  'llm',
  'n8n',
  'saas'
];

const blocked = [
  'legal',
  'lawyer',
  'attorney',
  'sales',
  'marketing',
  'hr',
  'finance',
  'recruiter',
  'designer',
  'seo',
  'writer',
  'copywriter',
  'account executive',
  'customer support'
];

const seen = new Set();
const clean = [];
const now = Date.now();
const maxAgeHours = 72;

for (const job of allJobs) {

  if (!job.title || !job.url) continue;

  if (job.source !== 'RSS') {

    const rawDate = job.posted_at || null;

    if (rawDate) {

      const parsedDate = new Date(rawDate).getTime();

      if (!isNaN(parsedDate)) {

        const ageHours =
          (now - parsedDate) /
          (1000 * 60 * 60);

        if (ageHours > maxAgeHours)
          continue;

      }

    }

  }

  const text = `${job.title} ${job.company} ${job.description} ${job.tags}`
    .toLowerCase();

  const hasAllowed =
    allowed.some(keyword =>
      text.includes(keyword.toLowerCase())
    );

  const hasBlocked =
    blocked.some(keyword =>
      text.includes(keyword.toLowerCase())
    );

  if (!hasAllowed || hasBlocked)
    continue;

  const key = job.url.toLowerCase();

  if (seen.has(key)) continue;

  seen.add(key);

  clean.push({
    json: {
      ...job,
      description: job.description.slice(0, 2000),
      status: 'new',
      created_at: new Date().toISOString()
    }
  });

  if (clean.length >= 200)
    break;

}

return clean;

