return $input.all().map((item, index) => {

  let parsed = {
    score: 0,
    reason: '',
    email_subject: '',
    email_body: ''
  };

  try {

    const raw =
      item.json.choices?.[0]?.message?.content || '';

    const cleaned = raw
      .replace(/```json/g, '')
      .replace(/```/g, '')
      .trim();

    parsed = JSON.parse(cleaned);

  } catch (e) {}

  const original = $('Limit').all()[index].json;

  return {
    json: {
      ...original,
      score: Number(parsed.score || 0),
      reason: parsed.reason || '',
      email_subject: parsed.email_subject || '',
      email_body: parsed.email_body || '',
      ai_processed_at: new Date().toISOString()
    }
  };

});

return $input.all().map((item, index) => {

  let parsed = {};

  try {

    const raw =
      item.json.choices?.[0]
      ?.message?.content || '';

    const cleaned = raw
      .replace(/```json/g, '')
      .replace(/```/g, '')
      .trim();

    parsed = JSON.parse(cleaned);

  } catch (e) {

    parsed = {};

  }

  const original =
    $('Parse AI Output')
      .all()[index]?.json || {};

  const website =
    parsed.website || '';

  const domain = website
    .replace('https://', '')
    .replace('http://', '')
    .replace('www.', '')
    .split('/')[0]
    .trim();

  return {
    json: {

      ...original,

      company_name:
        parsed.company_name ||
        original.company ||
        '',

      industry:
        parsed.industry || '',

      company_summary:
        parsed.company_summary || '',

      careers_url:
        parsed.careers_url || '',

      website,

      linkedin:
        parsed.linkedin || '',

      hr_email_guess:
        parsed.hr_email_guess || '',

      possible_hr_emails:
        domain
          ? [
              `careers@${domain}`,
              `jobs@${domain}`,
              `recruiting@${domain}`,
              `hr@${domain}`,
              `talent@${domain}`
            ]
          : [],

      enriched_at:
        new Date().toISOString()

    }
  };

});

